code.java:
public static int find(int[] nums, int target) {
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] == target) {
            return i;
        }
    }
    return -1;         // not found
}

public class Dog {
    private String name;      // fields
    private int tricks;

    public Dog(String name) { // constructor
        this.name = name;
        this.tricks = 0;
    }

    public void learn() {     // method
        tricks++;
    }

    public String getName() { return name; }
    public int getTricks() { return tricks; }
}

Dog rex = new Dog("Rex");   // create an object
rex.learn();
System.out.println(rex.getName() + " " + rex.getTricks());  // Rex 1

Dog rex = new Dog("Rex");
rex.learn();
rex.learn();
System.out.println(rex.getTricks());

